import zipfile
import re
import xml.etree.ElementTree as ET

NS = {
    'm': 'http://schemas.openxmlformats.org/spreadsheetml/2006/main',
    'r': 'http://schemas.openxmlformats.org/officeDocument/2006/relationships',
}

def col_to_idx(ref):
    letters = re.match(r'[A-Z]+', ref).group(0)
    idx = 0
    for ch in letters:
        idx = idx * 26 + (ord(ch) - 64)
    return idx

path = 'budget.xlsx'
zf = zipfile.ZipFile(path)
print("Files in archive:")
for n in zf.namelist():
    print(" ", n)

# workbook.xml -> sheets and r:id
wb_xml = ET.fromstring(zf.read('xl/workbook.xml'))
sheets = []
for s in wb_xml.find('m:sheets', NS):
    sheets.append((s.get('name'), s.get('{http://schemas.openxmlformats.org/officeDocument/2006/relationships}id')))
print("\nSheets:", sheets)

# rels
rels = ET.fromstring(zf.read('xl/_rels/workbook.xml.rels'))
rid_to_target = {}
for rel in rels:
    rid_to_target[rel.get('Id')] = rel.get('Target')
print("Rels:", rid_to_target)

# shared strings
shared = []
if 'xl/sharedStrings.xml' in zf.namelist():
    ss = ET.fromstring(zf.read('xl/sharedStrings.xml'))
    for si in ss.findall('m:si', NS):
        text = ''.join(t.text or '' for t in si.iter('{http://schemas.openxmlformats.org/spreadsheetml/2006/main}t'))
        shared.append(text)

for name, rid in sheets:
    target = rid_to_target[rid]
    if not target.startswith('xl/'):
        target = 'xl/' + target.lstrip('/')
    sheet_xml = ET.fromstring(zf.read(target))
    print(f"\n=== Sheet: {name} ({target}) ===")
    rows = {}
    max_col = 0
    for c in sheet_xml.iter('{http://schemas.openxmlformats.org/spreadsheetml/2006/main}c'):
        ref = c.get('r')
        t = c.get('t')
        v = c.find('m:v', NS)
        val = None
        if v is not None:
            val = v.text
            if t == 's':
                val = shared[int(val)]
            elif t in ('b',):
                val = val == '1'
            elif t == 'inlineStr':
                pass
            elif val is not None:
                try:
                    val = float(val)
                    if val.is_integer():
                        val = int(val)
                except ValueError:
                    pass
        if t == 'inlineStr':
            is_el = c.find('m:is', NS)
            val = ''.join(tt.text or '' for tt in is_el.iter('{http://schemas.openxmlformats.org/spreadsheetml/2006/main}t'))
        r = int(re.match(r'[A-Z]+(\d+)', ref).group(1))
        cidx = col_to_idx(ref)
        rows.setdefault(r, {})[cidx] = val
        max_col = max(max_col, cidx)
    for r in sorted(rows):
        print(r, [rows[r].get(c) for c in range(1, max_col + 1)])

